"""A small memoize decorator with hit/miss counters."""
import functools


def memoize(fn):
    cache = {}
    stats = {"hits": 0, "misses": 0}
    _MISSING = object()

    @functools.wraps(fn)
    def wrapper(*args, **kwargs):
        try:
            # kwargs sorted so that argument order does not matter; hashing the
            # key (in the cache lookup below) raises TypeError for unhashable
            # arguments, which we handle by not caching.
            key = (args, tuple(sorted(kwargs.items())))
            result = cache.get(key, _MISSING)
        except TypeError:
            # Unhashable arguments: still work, just don't cache.
            return fn(*args, **kwargs)
        if result is not _MISSING:
            stats["hits"] += 1
            return result
        stats["misses"] += 1
        result = fn(*args, **kwargs)
        cache[key] = result
        return result

    wrapper.cache_info = lambda: dict(stats, size=len(cache))

    def cache_clear():
        cache.clear()
        stats.update(hits=0, misses=0)

    wrapper.cache_clear = cache_clear
    return wrapper
