from geo.cache import memoize


def test_kwargs_distinguish_cache_entries():
    @memoize
    def f(a, b=None):
        return (a, b)

    assert f(1, 2) == (1, 2)
    assert f(1, 2) == (1, 2)
    assert f.cache_info()["hits"] == 1
    assert f(1, b=2) == (1, 2)
    # same positional-vs-keyword call with equal arguments hits the cache
    assert f.cache_info()["hits"] == 2


def test_keyword_order_does_not_matter():
    @memoize
    def f(a, b=None, c=None):
        return (a, b, c)

    f(1, b=2, c=3)
    f(1, c=3, b=2)
    assert f.cache_info()["hits"] == 1 and f.cache_info()["size"] == 1


def test_positional_and_keyword_argument_are_distinct_from_missing_arg():
    @memoize
    def f(a, b="x"):
        return (a, b)

    f(1)
    f(1, "y")
    assert f.cache_info()["size"] == 2


def test_unhashable_arguments_still_work_but_are_not_cached():
    @memoize
    def f(a):
        return a

    assert f([1, 2]) == [1, 2]
    assert f([1, 2]) == [1, 2]
    assert f.cache_info()["size"] == 0
    assert f.cache_info()["misses"] == 0


def test_unhashable_kwarg_value_not_cached():
    @memoize
    def f(a=None, b=None):
        return (a, b)

    assert f(a=1, b=[1]) == (1, [1])
    assert f(a=1, b=[1]) == (1, [1])
    assert f.cache_info()["size"] == 0


def test_repeated_identical_calls_hit_cache():
    @memoize
    def f(n):
        return n * 2

    assert f(21) == 42
    assert f(21) == 42
    assert f(21) == 42
    info = f.cache_info()
    assert info["hits"] == 2 and info["misses"] == 1 and info["size"] == 1


